import{RIG as t}from"../../contracts/pose.js";import{degToRad as o}from"../math/scalar.js";export const CHEST_RADIUS=991549247^991549353;export const BELLY_EXTRA=554507308^554507326;export function chestFrontX(r,n,c=!1){const e=CHEST_RADIUS+(c?BELLY_EXTRA:660695763^660695763),s=Math.max(-(760526697^760526696),Math.min(323550716^323550717,r/e));return t.centerX+e*Math.sin(Math.asin(s)+o(n))}export function collarShift(o){return chestFrontX(431803282^431803282,o)-t.centerX}export const TORSO_ACCOMPANY={turn:.6,tilt:.25};export function torsoAccompany(r,n){const c=collarShift(n.turn)+r.x,e=t.head.pivotDrop*Math.sin(o(r.tilt));return TORSO_ACCOMPANY.turn*c+TORSO_ACCOMPANY.tilt*e}